using System.ComponentModel.DataAnnotations;

namespace HospitalManagement.Application.DTOs;

public class MedicineDto { public int Id { get; set; } public string MedicineCode { get; set; } = string.Empty; public string MedicineName { get; set; } = string.Empty; public string GenericName { get; set; } = string.Empty; public string Manufacturer { get; set; } = string.Empty; public string Unit { get; set; } = string.Empty; public decimal UnitPrice { get; set; } public bool IsActive { get; set; } }
public class SaveMedicineDto { [Required, StringLength(20)] public string MedicineCode { get; set; } = string.Empty; [Required, StringLength(200)] public string MedicineName { get; set; } = string.Empty; [StringLength(200)] public string GenericName { get; set; } = string.Empty; [StringLength(200)] public string Manufacturer { get; set; } = string.Empty; [StringLength(50)] public string Unit { get; set; } = string.Empty; [Range(0, 999999.99)] public decimal UnitPrice { get; set; } public bool IsActive { get; set; } = true; }
public class InventoryDto { public int Id { get; set; } public int MedicineId { get; set; } public string MedicineName { get; set; } = string.Empty; public int AvailableQuantity { get; set; } public int ReorderLevel { get; set; } public DateTime? ExpiryDate { get; set; } public string? BatchNumber { get; set; } public string? SupplierName { get; set; } }
public class SaveInventoryDto { [Range(1, int.MaxValue)] public int MedicineId { get; set; } [Range(0, int.MaxValue)] public int AvailableQuantity { get; set; } [Range(0, int.MaxValue)] public int ReorderLevel { get; set; } public DateTime? ExpiryDate { get; set; } [StringLength(100)] public string? BatchNumber { get; set; } [StringLength(200)] public string? SupplierName { get; set; } }
